/**
 * @method
 * @name openIsuCodeWin
 * @description open Isu Code Win 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openIsuCodeWin = async function () {
    const frm = (document.NewListStkcertIsuStatDtlForm || { elements: [] });
    const isuCodeWin = {};
    isuCodeWin.isuCd = "";
    isuCodeWin.isuSrtCd = "";
    isuCodeWin.isuNm = "";
    isuCodeWin.isuSnm = "";
    isuCodeWin.isuEngNm = "";
    isuCodeWin.isuEngSnm = "";
    isuCodeWin.isuEngSymbl = "";
    isuCodeWin.isuRnd = "";
    isuCodeWin.isuDd = "";
    isuCodeWin.tarstkIsuCd = "";
    isuCodeWin.tarstkIsuNm = "";
    isuCodeWin.currIsoCd = "";
    isuCodeWin.secugrpId = "";
    isuCodeWin.calcelYn = "";
    const isurCd = $c.util.getComponent('form_5').isurCd.value;
    const url = "/jldfil55200n2/jldfil55200n2.xml?method=searchStkcertIsuDtlIsuCd&isurCd=" + isurCd;
    const style = "dialogWidth:580px;dialogHeight:300px;scroll:no;resize:no";
    Object.assign(isuCodeWin, (await $c.win.openPopup(url, { type: 'pageFramePopup', modal: true }, isuCodeWin)) || {});
    const stkcertKindCd = isuCodeWin.isuCd.substring(8, 11);
    if (isuCodeWin.calcelYn === 'N') {
        $c.util.getComponent("ipt_isuCd").setValue(isuCodeWin.isuCd);
        $c.util.getComponent("ipt_isuSrtCd").setValue(isuCodeWin.isuSrtCd);
        $c.util.getComponent("slc_currIsoCd").setValue(isuCodeWin.currIsoCd);
        if (isuCodeWin.secugrpId === 'DR') {
            $c.util.getComponent("slc_stkcertKindCd").setValue('KDR');
        } else {
            if (isuCodeWin.secugrpId === 'FS') {
                if (stkcertKindCd === '000') {
                    $c.util.getComponent("slc_stkcertKindCd").setValue('000');
                    $c.util.getComponent("ipt_isuKorNm").setValue("" + dma_newListApplContn.get("comAbbrv") + "" + "보통주");
                    $c.util.getComponent("ipt_isuKorAbbrv").setValue("" + dma_newListApplContn.get("comAbbrv") + "");
                    $c.util.getComponent("ipt_isuEngNm").setValue("" + dma_newListApplContn.get("comEngAbbrv") + "");
                    $c.util.getComponent("ipt_isuEngAbbrv").setValue("" + dma_newListApplContn.get("comEngAbbrv") + "");
                    $c.util.getComponent('ipt_isuKorNm').readOnly = true;
                    $c.util.getComponent('ipt_isuKorAbbrv').readOnly = true;
                    $c.util.getComponent('ipt_isuEngNm').readOnly = true;
                    $c.util.getComponent('ipt_isuEngAbbrv').readOnly = true;
                    $c.util.getComponent('dma_registerReq').set('prefstkTpCd', '0');
                    $c.util.getComponent('divPrefstkTpCd').hide();
                    $c.util.getComponent('divPrefstk').hide();
                }
            } else {
                const stkcertKindCdToken1 = document.stkcertKindCd.substring(0, 1);
                const stkcertKindCdToken2 = document.stkcertKindCd.substring(1, 2);
                const stkcertKindCdToken3 = document.stkcertKindCd.substring(2, 3);
                $c.util.getComponent("slc_stkcertKindCd").setValue(stkcertKindCd);
                let appendix = '';
                let appendix1 = '';
                let appendix2 = '';
                let appendix3 = '';
                let readonlyYn = true;
                if (stkcertKindCd === '000') {
                    appendix = '보통주';
                    appendix1 = '';
                    appendix2 = '';
                    appendix3 = '';
                    readonlyYn = true;
                    $c.util.getComponent('dma_registerReq').set('prefstkTpCd', '0');
                    $c.util.getComponent('divPrefstkTpCd').hide();
                    $c.util.getComponent('divPrefstk').hide();
                } else {
                    appendix = scwin.getStkcertKindCdTokenName1(stkcertKindCdToken1) + scwin.getStkcertKindCdTokenName2(stkcertKindCdToken2) + scwin.getStkcertKindCdTokenName3(stkcertKindCdToken3);
                    appendix1 = scwin.getStkcertKindCdTokenName11(stkcertKindCdToken1) + scwin.getStkcertKindCdTokenName21(stkcertKindCdToken2) + scwin.getStkcertKindCdTokenName31(stkcertKindCdToken3);
                    appendix2 = "(" + scwin.getStkcertKindCdTokenName12(stkcertKindCdToken1) + scwin.getStkcertKindCdTokenName22(stkcertKindCdToken2) + scwin.getStkcertKindCdTokenName32(stkcertKindCdToken3) + ")";
                    appendix3 = appendix2;
                    readonlyYn = false;
                    $c.util.getComponent('dma_registerReq').set('prefstkTpCd', '1');
                    $c.util.getComponent('divPrefstkTpCd').show();
                    $c.util.getComponent('divPrefstk').hide();
                }
                $c.util.getComponent("ipt_isuKorNm").setValue("" + dma_newListApplContn.get("comAbbrv") + "" + appendix);
                $c.util.getComponent("ipt_isuKorAbbrv").setValue("" + dma_newListApplContn.get("comAbbrv") + "" + appendix1);
                $c.util.getComponent("ipt_isuEngNm").setValue("" + dma_newListApplContn.get("comEngAbbrv") + "" + appendix2);
                $c.util.getComponent("ipt_isuEngAbbrv").setValue("" + dma_newListApplContn.get("comEngAbbrv") + "" + appendix3);
                $c.util.getComponent("ipt_isuEngSymbl").setValue("" + dma_newListApplContn.get("isurSymbl") + "");
                $c.util.getComponent('ipt_isuKorNm').readOnly = readonlyYn;
                $c.util.getComponent('ipt_isuKorAbbrv').readOnly = readonlyYn;
                $c.util.getComponent('ipt_isuEngNm').readOnly = readonlyYn;
                $c.util.getComponent('ipt_isuEngAbbrv').readOnly = readonlyYn;
            }
        }
    }
};

/**
 * @method
 * @name getStkcertKindCdTokenName1
 * @description get Stkcert Kind Cd Token Name1 처리
 * @param {*} token token
 * @returns {void}
 * @hidden N
 */
scwin.getStkcertKindCdTokenName1 = function (token) {
    let returnValue = '';
    switch (token) {
        case '0':
        returnValue = '보통';
        break;
        default:
        returnValue = token + "우선주";
        break;
    }
    return returnValue;
};

