scwin.newListApfm = async function (bzProcsNo, isurCd) {
    if (!await $c.win.confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\n 이동하시겠습니까?')) {
        return;
    }
    const frm = (document.NewListStkcertIsuStat || { elements: [] });
    frm.action = "lplAttach.do";
    $c.util.getComponent('dma_registerReq').set('method', "loadAttachForm");
    $c.util.getComponent("dma_registerReq").set("bzProcsNo", bzProcsNo);
    $c.util.getComponent("ipt_isurCd_3").setValue(isurCd);
    await scwin.tx_fn_newListApfm();
};

/**
 * @method
 * @name calCap
 * @description cal Cap 처리
 * @returns {void}
 * @hidden N
 */
scwin.calCap = function () {
    const frm = (document.NewListStkcertIsuStatDtlForm || { elements: [] });
    if ('' === $c.util.getComponent('ipt_isuShrs').getValue()) {
        return;
    } else {
        $c.util.getComponent("ipt_accIsuShrs").setValue($c.util.getComponent('ipt_isuShrs').getValue());
    }
    if ('' === $c.util.getComponent('ipt_parval').getValue()) {
        return;
    }
    const cap = (parseInt($c.util.getComponent('ipt_parval').getValue().replace(/^\$|,/g, "") + "")) * (parseInt($c.util.getComponent('ipt_isuShrs').getValue().replace(/^\$|,/g, "") + ""));
    if (cap === 0) {
        $c.util.getComponent("ipt_accIsuCap").setValue(cap);
        $c.util.getComponent("ipt_isuCap").setValue(cap);
    } else {
        $c.util.getComponent("ipt_accIsuCap").setValue($c.num.formatNumber(cap));
        $c.util.getComponent("ipt_isuCap").setValue($c.num.formatNumber(cap));
    }
};

/**
 * @method
 * @name calcuAccIsuShrs
 * @description calcu Acc Isu Shrs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuAccIsuShrs = async function () {
    try {
        const frm = (document.NewListStkcertIsuStatDtlForm || { elements: [] });
        if (($c.util.getComponent('ipt_bfAccIsuShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_bfAccIsuShrs').getValue())) === '') {
            $c.util.getComponent("ipt_bfAccIsuShrs").setValue(0);
        }
        if (($c.util.getComponent('ipt_isuShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_isuShrs').getValue())) === '') {
            $c.util.getComponent("ipt_isuShrs").setValue(0);
        }
        const sum = (parseInt($c.util.getComponent('ipt_bfAccIsuShrs').getValue().replace(/^\$|,/g, "") + "")) + (parseInt($c.util.getComponent('ipt_isuShrs').getValue().replace(/^\$|,/g, "") + ""));
        if (sum === 0) {
            $c.util.getComponent("ipt_accIsuShrs").setValue(sum);
        } else {
            $c.util.getComponent("ipt_accIsuShrs").setValue($c.num.formatNumber(sum));
        }
    } catch (err) { $c.exception.handleError(err, { notify: 'none', context: 'jldfil55320' });
        await $c.win.alert("[변경후 상장증권수 계산 중 오류]" + err);
    }
};

/**
 * @method
 * @name calcuIsuCap
 * @description calcu Isu Cap 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuIsuCap = async function () {
    const frm = (document.NewListStkcertIsuStatDtlForm || { elements: [] });
    const secugrpId = $c.util.getComponent('dma_registerReq').get('secugrpId');
    try {
        if (($c.util.getComponent('ipt_isuPrc').getValue() == null ? '' : String($c.util.getComponent('ipt_isuPrc').getValue())) === '') {
            $c.util.getComponent("ipt_isuPrc").setValue(0);
        }
        if (($c.util.getComponent('ipt_isuShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_isuShrs').getValue())) === '') {
            $c.util.getComponent("ipt_isuShrs").setValue(0);
        }
        if (($c.util.getComponent('ipt_parval').getValue() == null ? '' : String($c.util.getComponent('ipt_parval').getValue())) === '') {
            $c.util.getComponent("ipt_parval").setValue(0);
        }
        const rsnCd = $c.util.getComponent('slc_stkIsuRsnCd').getValue();
        let sum = 0;
        if (rsnCd === '118' || rsnCd === '160' || rsnCd === '170' || rsnCd === '171') {
            sum = 0;
        } else {
            if (rsnCd === '626' || rsnCd === '643' || rsnCd === '640' || rsnCd === '641') {
                sum = 0;
            } else {
                if (secugrpId === 'MF' || secugrpId === 'IF') {
                    sum = (parseFloat($c.util.getComponent('ipt_isuPrc').getValue().replace(/^\$|,/g, "") + "")) * (parseFloat($c.util.getComponent('ipt_isuShrs').getValue().replace(/^\$|,/g, "") + ""));
                } else {
                    sum = (parseFloat($c.util.getComponent('ipt_parval').getValue().replace(/^\$|,/g, "") + "")) * (parseFloat($c.util.getComponent('ipt_isuShrs').getValue().replace(/^\$|,/g, "") + ""));
                }
            }
        }
        if (sum === 0) {
            $c.util.getComponent("ipt_isuCap").setValue(sum);
        } else {
            $c.util.getComponent("ipt_isuCap").setValue($c.num.formatNumber(sum));
        }
    } catch (err) { $c.exception.handleError(err, { notify: 'none', context: 'jldfil55320' });
        await $c.win.alert("[증감 상장자본금 계산 중  오류]" + err);
    }
};

/**
 * @method
 * @name calcuAccIsuCap
 * @description calcu Acc Isu Cap 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuAccIsuCap = async function () {
    const frm = (document.NewListStkcertIsuStatDtlForm || { elements: [] });
    const secugrpId = $c.util.getComponent('dma_registerReq').get('secugrpId');
    if (secugrpId === "DR") {
        $c.util.getComponent("ipt_accIsuCap").setValue(0);
    } else {
        try {
            const rsnCd = $c.util.getComponent('slc_stkIsuRsnCd').getValue();
            let sum = '';
            if (($c.util.getComponent('ipt_bfAccIsuCap').getValue() == null ? '' : String($c.util.getComponent('ipt_bfAccIsuCap').getValue())) === '') {
                $c.util.getComponent("ipt_bfAccIsuCap").setValue(0);
            }
            if (($c.util.getComponent('ipt_isuCap').getValue() == null ? '' : String($c.util.getComponent('ipt_isuCap').getValue())) === '') {
                $c.util.getComponent("ipt_isuCap").setValue(0);
            }
            if (rsnCd === '118' || rsnCd === '160' || rsnCd === '170' || rsnCd === '171') {
                sum = (parseFloat($c.util.getComponent('ipt_bfAccIsuCap').getValue().replace(/^\$|,/g, "") + ""));
                $c.util.getComponent("ipt_isuCap").setValue(0);
            } else {
                if (rsnCd === '626' || rsnCd === '643' || rsnCd === '640' || rsnCd === '641') {
                    sum = (parseFloat($c.util.getComponent('ipt_bfAccIsuCap').getValue().replace(/^\$|,/g, "") + ""));
                    $c.util.getComponent("ipt_isuCap").setValue(0);
                } else {
                    await scwin.calcuIsuCap();
                    sum = (parseFloat($c.util.getComponent('ipt_bfAccIsuCap').getValue().replace(/^\$|,/g, "") + "")) + (parseFloat($c.util.getComponent('ipt_isuCap').getValue().replace(/^\$|,/g, "") + ""));
                }
            }
            if (sum === 0) {
                $c.util.getComponent("ipt_accIsuCap").setValue(sum);
            } else {
                $c.util.getComponent("ipt_accIsuCap").setValue($c.num.formatNumber(sum));
            }
        } catch (err) { $c.exception.handleError(err, { notify: 'none', context: 'jldfil55320' });
            await $c.win.alert("[변경후 상장자본금 계산 중  오류]" + err);
        }
    }
};

