 * @returns {void}
 * @hidden N
 */
scwin.showPreStkPanel = function (value) {
    if (!value) {
        $c.util.getComponent('divPrefstk').hide();
        $c.util.getComponent('dma_registerReq').set('prefstkTpCd', '1');
    } else {
        $c.util.getComponent('divPrefstk').show();
        $c.util.getComponent('dma_registerReq').set('prefstkTpCd', '2');
    }
    scwin.makeStkcertKindNm(value);
};

/**
 * @method
 * @name makeStkcertKindNm
 * @description make Stkcert Kind Nm 처리
 * @param {String} prefStkYn prefStkYn
 * @returns {void}
 * @hidden N
 */
scwin.makeStkcertKindNm = function (prefStkYn) {
    const frm = (document.NewListStkcertIsuStatDtlForm || { elements: [] });
    const stkcertKindCd = $c.util.getComponent('slc_stkcertKindCd').getValue();
    const stkcertKindCdToken1 = document.stkcertKindCd.substring(0, 1);
    const stkcertKindCdToken2 = document.stkcertKindCd.substring(1, 2);
    const stkcertKindCdToken3 = document.stkcertKindCd.substring(2, 3);
    let appendix = '';
    let appendix1 = '';
    let appendix2 = '';
    let appendix3 = '';
    let prefStkKorNm = '';
    let prefStkEngNm = '';
    if (prefStkYn) {
        prefStkKorNm = '(신형)';
        prefStkEngNm = 'B';
    }
    appendix = scwin.getStkcertKindCdTokenName1(stkcertKindCdToken1) + scwin.getStkcertKindCdTokenName2(stkcertKindCdToken2) + scwin.getStkcertKindCdTokenName3(stkcertKindCdToken3) + prefStkKorNm;
    appendix1 = scwin.getStkcertKindCdTokenName11(stkcertKindCdToken1) + scwin.getStkcertKindCdTokenName21(stkcertKindCdToken2) + scwin.getStkcertKindCdTokenName31(stkcertKindCdToken3) + prefStkEngNm;
    appendix2 = "(" + scwin.getStkcertKindCdTokenName12(stkcertKindCdToken1) + scwin.getStkcertKindCdTokenName22(stkcertKindCdToken2) + scwin.getStkcertKindCdTokenName32(stkcertKindCdToken3) + prefStkEngNm + ")";
    appendix3 = appendix2;
    $c.util.getComponent("ipt_isuKorNm").setValue("" + dma_newListApplContn.get("comAbbrv") + "" + appendix);
    $c.util.getComponent("ipt_isuKorAbbrv").setValue("" + dma_newListApplContn.get("comAbbrv") + "" + appendix1);
    $c.util.getComponent("ipt_isuEngNm").setValue("" + dma_newListApplContn.get("comEngAbbrv") + "" + appendix2);
    $c.util.getComponent("ipt_isuEngAbbrv").setValue("" + dma_newListApplContn.get("comEngAbbrv") + "" + appendix3);
};

/**
 * @method
 * @name test
 * @description test 처리
 * @returns {void}
 * @hidden N
 */
scwin.test = function () {
    const frm = (document.NewListStkcertIsuStatDtlForm || { elements: [] });
    const stkcertKindCd = '101';
    const stkcertKindCdToken1 = document.stkcertKindCd.substring(0, 1);
    const stkcertKindCdToken2 = document.stkcertKindCd.substring(1, 2);
    const stkcertKindCdToken3 = document.stkcertKindCd.substring(2, 3);
    $c.util.getComponent("slc_stkcertKindCd").setValue(stkcertKindCd);
    let appendix = '';
    let appendix1 = '';
    let appendix2 = '';
    let appendix3 = '';
    let readonlyYn = true;
    if (stkcertKindCd === '000') {
        appendix = '보통주';
        appendix1 = '';
        appendix2 = '';
        appendix3 = '';
        readonlyYn = true;
    } else {
        appendix = scwin.getStkcertKindCdTokenName1(stkcertKindCdToken1) + scwin.getStkcertKindCdTokenName2(stkcertKindCdToken2) + scwin.getStkcertKindCdTokenName3(stkcertKindCdToken3);
        appendix1 = scwin.getStkcertKindCdTokenName11(stkcertKindCdToken1) + scwin.getStkcertKindCdTokenName21(stkcertKindCdToken2) + scwin.getStkcertKindCdTokenName31(stkcertKindCdToken3);
        appendix2 = "(" + scwin.getStkcertKindCdTokenName12(stkcertKindCdToken1) + scwin.getStkcertKindCdTokenName22(stkcertKindCdToken2) + scwin.getStkcertKindCdTokenName32(stkcertKindCdToken3) + ")";
        appendix3 = appendix2;
        readonlyYn = false;
    }
    $c.util.getComponent("ipt_isuKorNm").setValue("" + dma_newListApplContn.get("comAbbrv") + "" + appendix);
    $c.util.getComponent("ipt_isuKorAbbrv").setValue("" + dma_newListApplContn.get("comAbbrv") + "" + appendix1);
    $c.util.getComponent("ipt_isuEngNm").setValue("" + dma_newListApplContn.get("comEngAbbrv") + "" + appendix2);
    $c.util.getComponent("ipt_isuEngAbbrv").setValue("" + dma_newListApplContn.get("comEngAbbrv") + "" + appendix3);
    $c.util.getComponent('ipt_isuKorNm').readOnly = readonlyYn;
    $c.util.getComponent('ipt_isuKorAbbrv').readOnly = readonlyYn;
    $c.util.getComponent('ipt_isuEngNm').readOnly = readonlyYn;
    $c.util.getComponent('ipt_isuEngAbbrv').readOnly = readonlyYn;
};

